def kthSubarraySum(nums, k):
    def count(limit):
        total = left = window = 0
        for right, x in enumerate(nums):
            window += x
            while window > limit:
                window -= nums[left]
                left += 1
            total += right - left + 1
        return total

    lo, hi = min(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if count(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
